DROP PROCEDURE IF EXISTS `sp_visual_read_shape_freshness_get`$$
CREATE DEFINER=`root`@`%` PROCEDURE `sp_visual_read_shape_freshness_get` (IN `p_shape_key` VARCHAR(64))   SELECT
    f.shape_key,
    f.refreshed_utc,
    f.is_seed_content,
    f.row_count
FROM (
    SELECT
        'work_order_lookup' AS shape_key,
        MAX(refreshed_utc) AS refreshed_utc,
        CASE WHEN COUNT(*) = 0 OR SUM(is_seed_content) = COUNT(*) THEN 1 ELSE 0 END AS is_seed_content,
        COUNT(*) AS row_count
    FROM visual_work_order_lookup_result

    UNION ALL

    SELECT
        'operation_sequences' AS shape_key,
        MAX(refreshed_utc) AS refreshed_utc,
        CASE WHEN COUNT(*) = 0 OR SUM(is_seed_content) = COUNT(*) THEN 1 ELSE 0 END AS is_seed_content,
        COUNT(*) AS row_count
    FROM visual_operation_sequences_result

    UNION ALL

    SELECT
        'subordinate_parts' AS shape_key,
        MAX(refreshed_utc) AS refreshed_utc,
        CASE WHEN COUNT(*) = 0 OR SUM(is_seed_content) = COUNT(*) THEN 1 ELSE 0 END AS is_seed_content,
        COUNT(*) AS row_count
    FROM visual_subordinate_parts_result

    UNION ALL

    SELECT
        'inventory_locations' AS shape_key,
        MAX(refreshed_utc) AS refreshed_utc,
        CASE WHEN COUNT(*) = 0 OR SUM(is_seed_content) = COUNT(*) THEN 1 ELSE 0 END AS is_seed_content,
        COUNT(*) AS row_count
    FROM visual_inventory_locations_result

    UNION ALL

    SELECT
        'disposition_input' AS shape_key,
        MAX(refreshed_utc) AS refreshed_utc,
        CASE WHEN COUNT(*) = 0 OR SUM(is_seed_content) = COUNT(*) THEN 1 ELSE 0 END AS is_seed_content,
        COUNT(*) AS row_count
    FROM visual_disposition_input_result
) AS f
WHERE p_shape_key IS NULL OR f.shape_key = p_shape_key
ORDER BY f.shape_key$$

DROP PROCEDURE IF EXISTS `sp_visual_read_shape_metadata_get`$$
CREATE DEFINER=`root`@`%` PROCEDURE `sp_visual_read_shape_metadata_get` (IN `p_shape_key` VARCHAR(64))   SELECT
    k.shape_key,
    (SELECT COUNT(*)
       FROM information_schema.tables tb
      WHERE tb.table_schema = DATABASE()
        AND tb.table_name = CONCAT('visual_', k.shape_key, '_result')) AS mirror_table_exists,
    (SELECT COUNT(*)
       FROM information_schema.tables tb
      WHERE tb.table_schema = DATABASE()
        AND tb.table_name = CONCAT('visual_', k.shape_key, '_result_stage')) AS stage_table_exists,
    (SELECT COUNT(*)
       FROM information_schema.routines r
      WHERE r.routine_schema = DATABASE()
        AND r.routine_name = CONCAT('sp_visual_', k.shape_key, '_get')) AS get_procedure_exists,
    (SELECT COUNT(*)
       FROM information_schema.routines r
      WHERE r.routine_schema = DATABASE()
        AND r.routine_name = CONCAT('sp_visual_', k.shape_key, '_refresh')) AS refresh_procedure_exists,
    (SELECT GROUP_CONCAT(c.column_name ORDER BY c.ordinal_position)
       FROM information_schema.columns c
      WHERE c.table_schema = DATABASE()
        AND c.table_name = CONCAT('visual_', k.shape_key, '_result')) AS mirror_columns
FROM (
    SELECT DISTINCT SUBSTRING(tb.table_name, 8, CHAR_LENGTH(tb.table_name) - 14) AS shape_key
      FROM information_schema.tables tb
     WHERE tb.table_schema = DATABASE()
       AND tb.table_name LIKE 'visual\_%\_result'
    UNION
    SELECT p_shape_key FROM DUAL
) AS k
WHERE k.shape_key IS NOT NULL
  AND (p_shape_key IS NULL OR k.shape_key = p_shape_key)
ORDER BY k.shape_key$$

DROP PROCEDURE IF EXISTS `sp_visual_subordinate_parts_get`$$
CREATE DEFINER=`root`@`%` PROCEDURE `sp_visual_subordinate_parts_get` (IN `p_normalized_work_order` VARCHAR(64), IN `p_part_number` VARCHAR(64), IN `p_sequence_number` INT)   SELECT
